#!/usr/bin/env bash
######################################################################
# .what = a fixture rule whose EXIT trap names its own file, and which
#         blocks a payload that holds `deny`
######################################################################
set -euo pipefail
trap 'echo "trap fired in ${0##*/}, src=${BASH_SOURCE[0]##*/}" >&2' EXIT
payload=$(cat)
if [[ "$payload" == *deny* ]]; then
  echo "✋ trap.sh refuses" >&2
  exit 2
fi
echo "trap.sh saw ${#payload} bytes"
